	format	binary as 'elf'
	processor cpu64_v8 +cpu64_fp +cpu64_simd
	code64
ELF_BASE = 4000000000h
	org	0
armpi_base:
	db	7Fh,'ELF',2,1,1,0
	dd	0
	dh	2,183
	dw	1
	dd	ELF_BASE + armpi_entry
	dd	64
	dd	0
	dw	0
	dh	64,56,1,64,0,0
	dw	1,7
	dd	0,ELF_BASE,ELF_BASE,armpi_file_end,armpi_mem_end,1000h

; ===========================================================================
;  Execution ARMPI : demarrage, pile x86 emulee, appels systeme Linux i386
;  emules (int 0x80) au-dessus des appels systeme ARMPI.
; ===========================================================================
ARMPI_SYS_EXIT	= 0x10
ARMPI_SYS_PRINT	= 0x60
ARMPI_SYS_TIME	= 0x19
ARMPI_SYS_SBRK	= 0x00
ARMPI_SYS_OPEN	= 0x80
ARMPI_SYS_READ	= 0x81
ARMPI_SYS_WRITE	= 0x82
ARMPI_SYS_SEEK	= 0x83
ARMPI_SYS_CLOSE	= 0x84
ARMPI_SYS_LIB_OPEN = 0x64
ARMPI_APPKIT_FSYS = 13			; rang de fichier_sys dans appkit.abi (version 14)

armpi_entry:
	adr	x28,armpi_base
	mov	x19,x0				; ligne d'arguments (adresse absolue) ou 0
	adr	x0,armpi_appkit			; fichiers par le client d'AppKit
	mov	x1,ARMPI_APPKIT_FSYS+1		; (docs/FICHIERS.md, etape 3) ;
	mov	x8,ARMPI_SYS_LIB_OPEN		; sans lui : par le noyau
	svc	0
	tbnz	x0,63,.sans_appkit
	ldr	w1,[x0,8+ARMPI_APPKIT_FSYS*4]
	add	x1,x0,x1
	adr	x2,armpi_fsys
	str	x1,[x2]
.sans_appkit:
	movz	w20,armpi_argbuf and 0FFFFh
	movk	w20,(armpi_argbuf shr 16) and 0FFFFh,lsl 16
	movz	w21,armpi_argv and 0FFFFh
	movk	w21,(armpi_argv shr 16) and 0FFFFh,lsl 16
	movz	w9,armpi_name and 0FFFFh
	movk	w9,(armpi_name shr 16) and 0FFFFh,lsl 16
	str	w9,[x28,w21,uxtw]
	mov	w22,1				; argc
	cbz	x19,.args_done
.skip:	ldrb	w9,[x19]
	cbz	w9,.args_done
	cmp	w9,' '
	b.hi	.word
	add	x19,x19,1
	b	.skip
.word:	cmp	w22,30
	b.hs	.args_done
	add	w10,w21,w22,lsl 2
	str	w20,[x28,w10,uxtw]
	add	w22,w22,1
.copy:	ldrb	w9,[x19]
	cmp	w9,' '
	b.ls	.end_word
	strb	w9,[x28,w20,uxtw]
	add	w20,w20,1
	add	x19,x19,1
	b	.copy
.end_word:
	strb	wzr,[x28,w20,uxtw]
	add	w20,w20,1
	b	.skip
.args_done:
	; pile x86 : argc, argv[], 0, 0 (environnement vide)
	movz	w4,armpi_stack_top and 0FFFFh
	movk	w4,(armpi_stack_top shr 16) and 0FFFFh,lsl 16
	add	w9,w22,3
	sub	w4,w4,w9,lsl 2
	str	w22,[x28,w4,uxtw]
	mov	w10,0
.argv:	cmp	w10,w22
	b.hs	.argv_done
	add	w11,w21,w10,lsl 2
	ldr	w12,[x28,w11,uxtw]
	add	w11,w4,4
	add	w11,w11,w10,lsl 2
	str	w12,[x28,w11,uxtw]
	add	w10,w10,1
	b	.argv
.argv_done:
	add	w11,w4,4
	add	w11,w11,w22,lsl 2
	str	wzr,[x28,w11,uxtw]
	add	w11,w11,4
	str	wzr,[x28,w11,uxtw]
	mov	w0,0
	mov	w1,0
	mov	w2,0
	mov	w3,0
	mov	w5,0
	mov	w6,0
	mov	w7,0
	b	start

; int 0x80 : eax = numero Linux i386, ebx, ecx, edx = arguments -> eax
; Preserve tous les registres x86 (w1-w7), NZCV, x19-x28.
linux_int80:
	mrs	x9,nzcv
	stp	x9,x30,[sp,-16]!
	stp	x1,x2,[sp,-16]!
	cmp	w0,1
	b.eq	.exit
	cmp	w0,3
	b.eq	.read
	cmp	w0,4
	b.eq	.write
	cmp	w0,5
	b.eq	.open
	cmp	w0,6
	b.eq	.close
	cmp	w0,13
	b.eq	.time
	cmp	w0,19
	b.eq	.lseek
	cmp	w0,45
	b.eq	.brk
	cmp	w0,78
	b.eq	.gtod
	movn	w0,37				; -38 ENOSYS
	b	.ret
.exit:	mov	w0,w3
	mov	x8,ARMPI_SYS_EXIT
	svc	0
.read:	cmp	w3,3
	b.lo	.zero
	sub	w0,w3,3
	add	x1,x28,w1,uxtw
	mov	w2,w2
	mov	x8,ARMPI_SYS_READ
	bl	armpi_fichier
	b	.ret
.write:	cmp	w3,3
	b.lo	.print
	sub	w0,w3,3
	add	x1,x28,w1,uxtw
	mov	w2,w2
	mov	x8,ARMPI_SYS_WRITE
	bl	armpi_fichier
	b	.ret
.print:	add	x9,x28,w1,uxtw			; sortie standard (AppKit : console ou
	mov	w10,w2				; tube, etape 4), par blocs de 4096
.pr:	cbz	w10,.pr_done
	mov	w11,4096
	cmp	w10,w11
	csel	w11,w10,w11,lo
	mov	x0,x9
	mov	w1,w11
	mov	x8,ARMPI_SYS_PRINT
	bl	armpi_fichier
	add	x9,x9,x11
	sub	w10,w10,w11
	b	.pr
.pr_done:
	ldr	x2,[sp,8]
	mov	w0,w2
	b	.ret
.open:	add	x0,x28,w3,uxtw
	and	w9,w1,3
	mov	w10,1				; O_READ
	cmp	w9,1
	b.ne	.o1
	mov	w10,2				; O_WRITE
.o1:	cmp	w9,2
	b.ne	.o2
	mov	w10,3
.o2:	tst	w1,64				; O_CREAT
	b.eq	.o3
	orr	w10,w10,4
.o3:	tst	w1,512				; O_TRUNC
	b.eq	.o4
	orr	w10,w10,8
.o4:	mov	w1,w10
	mov	x8,ARMPI_SYS_OPEN
	bl	armpi_fichier
	tbnz	x0,63,.ret
	add	w0,w0,3
	b	.ret
.close:	cmp	w3,3
	b.lo	.zero
	sub	w0,w3,3
	mov	x8,ARMPI_SYS_CLOSE
	bl	armpi_fichier
	b	.ret
.time:	cbz	w3,.zero
	str	wzr,[x28,w3,uxtw]
	b	.zero
.lseek:	sub	w0,w3,3
	sxtw	x1,w1
	mov	w2,w2
	mov	x8,ARMPI_SYS_SEEK
	bl	armpi_fichier
	b	.ret
.brk:	adr	x9,armpi_brk
	ldr	w10,[x9]
	cbnz	w10,.brk_ok
	mov	x0,0
	mov	x8,ARMPI_SYS_SBRK
	svc	0
	sub	x10,x0,x28
	str	w10,[x9]
.brk_ok:
	cmp	w3,w10
	b.ls	.brk_cur
	sub	w0,w3,w10
	mov	x8,ARMPI_SYS_SBRK
	svc	0
	tbnz	x0,63,.brk_cur
	str	w3,[x9]
	mov	w10,w3
.brk_cur:
	mov	w0,w10
	b	.ret
.gtod:	mov	x8,ARMPI_SYS_TIME
	svc	0
	mov	x10,1000
	udiv	x11,x0,x10
	msub	x12,x11,x10,x0
	mul	x12,x12,x10
	str	w11,[x28,w3,uxtw]
	add	w13,w3,4
	str	w12,[x28,w13,uxtw]
.zero:	mov	w0,0
.ret:	ldp	x1,x2,[sp],16
	ldp	x9,x30,[sp],16
	msr	nzcv,x9
	ret

; x8 = appel de fichier : fichier_sys d'AppKit (memes registres rendus qu'un
; svc 0 ; x16 : relais), le noyau si AppKit manque
armpi_fichier:
	adr	x16,armpi_fsys
	ldr	x16,[x16]
	cbz	x16,.noyau
	br	x16
.noyau:	svc	0
	ret

armpi_name	db 'fasmarm',0
armpi_appkit	db 'appkit',0
		align 8
armpi_fsys	dd 0				; fichier_sys d'AppKit (0 : aucun)
armpi_brk	dw 0
	stdin	= 0
	stdout	= 1
	stderr	= 2
	align 4
start:
				; mov [con_handle],stdout  [armpi_main.asm:18]
